"""Checks /app/out/tables.json against the approved tables for the survey in /app/data.

Runs /app/bin/crosstabs.py on /app/data and on a copy of it in another
directory, then reports which summary figures agree with the approved ones
and, per table, how many entries (bases, weighted bases and values) agree,
naming up to three that do not. The approved figures are stored only as
salted digests, so the check cannot say what a figure should be, only whether
it is the same count, or within 0.01 of the number (docs/output.md 4.2).
"""
import hashlib
import json
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

SCRIPT = Path("/app/bin/crosstabs.py")
DATA = Path("/app/data")
OUTPUT = Path("/app/out/tables.json")
DIGESTS = Path(__file__).with_name("approved-tables.json")
COUNTS = ("rows", "duplicates", "short_partials", "speeders", "complete", "partial")


def digest(salt, key, text):
    return hashlib.sha256(f"{salt}|{key}|{text}".encode()).hexdigest()[:24]


def candidates(v, count):
    if v is None:
        return ["null"]
    if isinstance(v, bool) or not isinstance(v, (int, float)):
        return []
    if count:
        return [str(v)] if isinstance(v, int) else []
    base = round(v, 2)
    return [f"{round(base + d, 2) + 0.0:.2f}" for d in (0.0, 0.01, -0.01)]


def matches(approved, key, v, count=False):
    want = approved["entries"].get(key)
    return want is not None and any(digest(approved["salt"], key, c) == want for c in candidates(v, count))


def run(data, out):
    try:
        p = subprocess.run([sys.executable, str(SCRIPT), str(data), str(out)], capture_output=True, text=True,
                           timeout=600)
    except subprocess.TimeoutExpired:
        return None, "the script did not finish within 600 seconds"
"""Runs bin/crosstabs.py on each small survey under tests/fixtures and compares
the tables file with the reviewed one next to it, to 0.01 as docs/output.md 4.2
says.

From /app: python -m unittest discover -s tests -t .
"""
import json
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

HERE = Path(__file__).resolve().parent
SCRIPT = HERE.parent / "bin" / "crosstabs.py"
FIXTURES = HERE / "fixtures"
COUNTS = ("rows", "duplicates", "short_partials", "speeders", "complete", "partial")


def build(case):
    with tempfile.TemporaryDirectory() as td:
        out = Path(td) / "tables.json"
        p = subprocess.run([sys.executable, str(SCRIPT), str(FIXTURES / case / "input"), str(out)],
                           capture_output=True, text=True, timeout=120)
        if p.returncode:
            raise AssertionError(f"crosstabs.py exited with status {p.returncode}:\n{p.stderr[-2000:]}")
        return json.loads(out.read_text(encoding="utf-8"))


def agrees(got, want):
    if got is None or want is None:
        return got is None and want is None
    if isinstance(got, bool) or not isinstance(got, (int, float)):
        return False
    return abs(got - want) <= 0.011


def is_count(v):
    return isinstance(v, int) and not isinstance(v, bool)


def first_difference(got, want):
    if not isinstance(got, dict) or set(got) != {"survey", "summary", "tables"}:
        return "the output is not an object with exactly the keys survey, summary and tables"
    if got["survey"] != want["survey"]:
        return f"survey {got['survey']!r}, expected {want['survey']!r}"
    s, w = got["summary"], want["summary"]
    if not isinstance(s, dict) or set(s) != set(w):
        return f"summary keys {sorted(s) if isinstance(s, dict) else s!r}, expected {sorted(w)}"
    versions = s["versions"] if isinstance(s["versions"], list) else []
    if [v.get("version") if isinstance(v, dict) else None for v in versions] != [v["version"] for v in w["versions"]]:
        return f"summary versions {versions!r}, expected versions {[v['version'] for v in w['versions']]}"
    for g, e in zip(versions, w["versions"]):
        if set(g) != set(e):
            return f"summary version {e['version']}: keys {sorted(g)}, expected {sorted(e)}"
        for k in COUNTS:
            if not is_count(g[k]) or g[k] != e[k]:
                return f"summary version {e['version']} {k}: {g[k]!r}, expected {e[k]}"
    if not is_count(s["respondents"]) or s["respondents"] != w["respondents"]:
        return f"summary respondents: {s['respondents']!r}, expected {w['respondents']}"

