#!/usr/bin/env python3
"""Residents survey: response summary and weighted crosstabs (see /app/docs)."""
import csv
import io
import json
import sys
from datetime import datetime, timedelta, timezone
from pathlib import Path


def load_json(p):
    return json.loads(Path(p).read_text(encoding="utf-8-sig"))


def read_exports(d):
    rows = []
    files = sorted(p for p in (Path(d) / "exports").iterdir() if p.is_file() and p.name.endswith(".csv"))
    for p in files:
        text = p.read_bytes().decode("utf-8")
        if text.startswith("﻿"):
            text = text[1:]
        first = text.replace("\r\n", "\n").split("\n", 1)[0]
        delim = next((c for c in (",", ";", "\t") if c in first), ",")
        rd = csv.reader(io.StringIO(text, newline=""), delimiter=delim)
        header = None
        for rec in rd:
            if header is None:
                header = [h.strip() for h in rec]
                continue
            cells = [c.strip() for c in rec]
            if not any(cells):
                continue
            row = {}
            for h, c in zip(header, cells):
                if h not in row or c != "":
                    row[h] = c if c != "" else None
            rows.append(row)
    return rows


def parse_offset(s):
    sign = -1 if s[0] == "-" else 1
    h, m = s[1:].split(":")
    return timezone(sign * timedelta(hours=int(h), minutes=int(m)))


def parse_time(s, meta):
    if s is None:
        return None
    if meta.get("submitted_format") == "local":
        dt = datetime.strptime(s, "%Y-%m-%d %H:%M:%S").replace(tzinfo=parse_offset(meta["utc_offset"]))
    else:
        if s.endswith("Z") or s.endswith("z"):
            s = s[:-1] + "+00:00"
        dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


def parse_duration(s, meta):
    if s is None:
        return None
    if meta.get("duration_format") == "clock":
        parts = [int(x) for x in s.split(":")]
        t = 0
        for x in parts:
            t = t * 60 + x
        return t
    return int(float(s))


def to_int(v):
    try:
        return int(v)
    except ValueError:
        return int(float(v))


def median(xs):
    xs = sorted(xs)
    n = len(xs)
    return xs[n // 2] if n % 2 else (xs[n // 2 - 1] + xs[n // 2]) / 2


def recode_val(entry, v):
    rc = entry.get("recode")
    if rc is not None:
        return rc[v]
    return to_int(v)


def read_answer(q, entry, row, ref_year):
    """Return a code, a frozenset of codes, or None (valid answer, rule 4)."""
    t = q["type"]
    if t == "multi":
        chosen = set()
        if "columns" in entry:
            for code, col in entry["columns"].items():
                if row.get(col) == "1":
                    chosen.add(to_int(code))
        else:
            cell = row.get(entry["column"])
            if cell is not None:
                for el in cell.split(entry["separator"]):
                    el = el.strip()
                    if el:
                        chosen.add(recode_val(entry, el))
        if not chosen:
            return None
        excl = {o["code"] for o in q["options"] if o.get("exclusive")}
        non = chosen - excl
        if non and chosen & excl:
            chosen = non
        elif len(chosen) >= 2 and not non:
            return None
        miss = {o["code"] for o in q["options"] if o.get("missing")}
        chosen -= miss
        return frozenset(chosen) if chosen else None
    v = row.get(entry["column"])
    if v is None:
        return None
    if t == "single":
        code = recode_val(entry, v)
        if any(o["code"] == code and o.get("missing") for o in q["options"]):
            return None
        return code
    src = entry.get("source")
    if src == "band":
        return recode_val(entry, v)
    age = to_int(v)
    if src == "birth_year":
        age = ref_year - age
    for b in q["bands"]:
        if b["min"] <= age <= b["max"]:
            return b["code"]
    return None


def main(inp, outp):
    inp = Path(inp)
    cb = load_json(inp / "codebook.json")
    wt = load_json(inp / "weighting.json")
    plan = load_json(inp / "tables.json")
    versions = cb["versions"]
    vkeys = list(versions)
    ref_year = int(cb["reference_date"][:4])
    min_page = cb["partial_min_page"]
    qs = {q["id"]: q for q in cb["questions"]}

    stats = {k: {"rows": 0, "duplicates": 0, "short_partials": 0, "speeders": 0, "complete": 0, "partial": 0}
             for k in vkeys}
    recs = []
    for row in read_exports(inp):
        vk = row.get("form_version")
        if vk not in versions:
            continue
        m = versions[vk]["meta"]
        stats[vk]["rows"] += 1
        lp = row.get(m["last_page"])
        complete = row.get(m["status"]) == m["complete"]
        recs.append({
            "v": vk, "row": row, "id": row.get(m["id"]), "complete": complete,
            "t": parse_time(row.get(m["submitted"]), m),
            "dur": parse_duration(row.get(m["duration"]), m),
            "lp": to_int(lp) if lp is not None else 0,
        })

    # 1. duplicates
    best = {}
    for r in recs:
        b = best.get(r["id"])
        if b is None or (r["complete"], r["t"]) > (b["complete"], b["t"]):
            best[r["id"]] = r
    kept = []
    for r in recs:
        if best[r["id"]] is r:
            kept.append(r)
        else:
            stats[r["v"]]["duplicates"] += 1
    # 2. short partials
    k2 = []
    for r in kept:
        if not r["complete"] and r["lp"] < min_page:
            stats[r["v"]]["short_partials"] += 1
        else:
            k2.append(r)
    # 3. speeders
    med = {}
    for vk in vkeys:
        ds = [r["dur"] for r in k2 if r["v"] == vk and r["complete"] and r["dur"] is not None]
        med[vk] = median(ds) if ds else None
    k3 = []
    for r in k2:
        if r["complete"] and r["dur"] is not None and med[r["v"]] is not None and r["dur"] * 5 < med[r["v"]] * 2:
            stats[r["v"]]["speeders"] += 1
        else:
            k3.append(r)
    for r in k3:
        stats[r["v"]]["complete" if r["complete"] else "partial"] += 1

    # 4. asked / answers
    for r in k3:
        asked, ans = {}, {}
        for q in cb["questions"]:
            e = q["versions"].get(r["v"])
            ok = e is not None and (r["complete"] or e["page"] <= r["lp"])
            if ok and q.get("ask_if"):
                a = q["ask_if"]
                prev = ans.get(a["question"])
                if prev is None:
                    ok = False
                elif isinstance(prev, frozenset):
                    ok = bool(prev & set(a["codes"]))
                else:
                    ok = prev in a["codes"]
            asked[q["id"]] = ok
            ans[q["id"]] = read_answer(q, e, r["row"], ref_year) if ok else None
        r["ans"] = ans

    n = len(k3)
    # 5. weights
    w = [1.0] * n
    dims = []
    for d in wt["dimensions"]:
        qid = d["question"]
        present = {r["ans"].get(qid) for r in k3}
        tg = {to_int(k): float(v) for k, v in d["targets"].items() if to_int(k) in present}
        tot = sum(tg.values())
        if not tg or tot <= 0:
            continue
        groups = {c: [] for c in tg}
        for i, r in enumerate(k3):
            a = r["ans"].get(qid)
            if a in groups:
                groups[a].append(i)
        dims.append(({c: s / tot for c, s in tg.items()}, groups))
    if n:
        for _ in range(wt["max_iterations"]):
            done = True
            for shares, groups in dims:
                T = sum(w[i] for g in groups.values() for i in g)
                facs = {}
                for c, g in groups.items():
                    W = sum(w[i] for i in g)
                    facs[c] = shares[c] * T / W if W else 1.0
                for c, g in groups.items():
                    for i in g:
                        w[i] *= facs[c]
                    if abs(facs[c] - 1) > wt["tolerance"]:
                        done = False
            if done:
                break
        m = sum(w) / n
        hi, lo = wt["cap"] * m, wt["floor"] * m
        w = [min(max(x, lo), hi) for x in w]
        m = sum(w) / n
        w = [x / m for x in w]

    # 6. tables
    columns = [("total", None, None)]
    for bq in plan["banner"]:
        q = qs[bq]
        items = q["bands"] if q["type"] == "age" else [o for o in q["options"] if not o.get("missing")]
        for o in items:
            if o.get("missing"):
                continue
            columns.append((f"{bq}:{o['code']}", bq, o["code"]))

    def r2(x):
        return round(x, 2) + 0.0

    tables = []
    for t in plan["tables"]:
        q = qs[t["question"]]
        multi = q["type"] == "multi"
        opts = [o for o in q["options"] if not o.get("missing")]
        scores = {o["code"]: o.get("score") for o in opts}
        cols = []
        for cid, bq, bc in columns:
            members = [i for i, r in enumerate(k3)
                       if r["ans"].get(q["id"]) is not None and (bq is None or r["ans"].get(bq) == bc)]
            wb = sum(w[i] for i in members)
            col = {"column": cid, "base": len(members), "weighted_base": r2(wb)}
            vals = {}

            def has(i, codes):
                a = k3[i]["ans"][q["id"]]
                return bool(a & set(codes)) if multi else a in codes

            def pct(codes):
                if not members:
                    return None
                return r2(100 * sum(w[i] for i in members if has(i, codes)) / wb)

            for o in opts:
                vals[str(o["code"])] = pct([o["code"]])
            for net in t.get("nets", []):
                vals[net["id"]] = pct(net["codes"])
            if t.get("mean"):
                vals["mean"] = (r2(sum(w[i] * scores[k3[i]["ans"][q["id"]]] for i in members) / wb)
                                if members else None)
            col["values"] = vals
            cols.append(col)
        tables.append({"table": t["id"], "columns": cols})

    summary = {
        "versions": [dict(version=k, **stats[k]) for k in vkeys],
        "respondents": n,
        "effective_n": r2(sum(w) ** 2 / sum(x * x for x in w)) if n else None,
        "weight_min": r2(min(w)) if n else None,
        "weight_max": r2(max(w)) if n else None,
    }
    out = {"survey": cb["survey"], "summary": summary, "tables": tables}
    Path(outp).write_text(json.dumps(out, indent=1), encoding="utf-8")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
