        tg = {to_int(k): float(v) for k, v in d["targets"].items() if to_int(k) in present}
        tot = sum(tg.values())
        if not tg or tot <= 0:
            continue
        groups = {c: [] for c in tg}
        for i, r in enumerate(k3):
            a = r["ans"].get(qid)
            if a in groups:
                groups[a].append(i)
        dims.append(({c: s / tot for c, s in tg.items()}, groups))
    if n:
        for _ in range(wt["max_iterations"]):
            done = True
            for shares, groups in dims:
                T = sum(w[i] for g in groups.values() for i in g)
                facs = {}
                for c, g in groups.items():
                    W = sum(w[i] for i in g)
                    facs[c] = shares[c] * T / W if W else 1.0
                for c, g in groups.items():
                    for i in g:
                        w[i] *= facs[c]
                    if abs(facs[c] - 1) > wt["tolerance"]:
                        done = False
            if done:
                break
        m = sum(w) / n
        hi, lo = wt["cap"] * m, wt["floor"] * m
        w = [min(max(x, lo), hi) for x in w]
        m = sum(w) / n
        w = [x / m for x in w]

    # 6. tables
    columns = [("total", None, None)]
    for bq in plan["banner"]:
        q = qs[bq]
        items = q["bands"] if q["type"] == "age" else [o for o in q["options"] if not o.get("missing")]
        for o in items:
            if o.get("missing"):
                continue
            columns.append((f"{bq}:{o['code']}", bq, o["code"]))

    def r2(x):
        return round(x, 2) + 0.0

    tables = []
    for t in plan["tables"]:
        q = qs[t["question"]]
        multi = q["type"] == "multi"
        opts = [o for o in q["options"] if not o.get("missing")]
        scores = {o["code"]: o.get("score") for o in opts}
        cols = []
        for cid, bq, bc in columns:
            members = [i for i, r in enumerate(k3)
                       if r["ans"].get(q["id"]) is not None and (bq is None or r["ans"].get(bq) == bc)]
            wb = sum(w[i] for i in members)
            col = {"column": cid, "base": len(members), "weighted_base": r2(wb)}
            vals = {}

            def has(i, codes):
                a = k3[i]["ans"][q["id"]]
                return bool(a & set(codes)) if multi else a in codes

            def pct(codes):
                if not members:
                    return None
                return r2(100 * sum(w[i] for i in members if has(i, codes)) / wb)

            for o in opts:
                vals[str(o["code"])] = pct([o["code"]])
            for net in t.get("nets", []):
                vals[net["id"]] = pct(net["codes"])
            if t.get("mean"):
                vals["mean"] = (r2(sum(w[i] * scores[k3[i]["ans"][q["id"]]] for i in members) / wb)
                                if members else None)
            col["values"] = vals
            cols.append(col)
        tables.append({"table": t["id"], "columns": cols})

    summary = {
        "versions": [dict(version=k, **stats[k]) for k in vkeys],
        "respondents": n,
        "effective_n": r2(sum(w) ** 2 / sum(x * x for x in w)) if n else None,
        "weight_min": r2(min(w)) if n else None,
        "weight_max": r2(max(w)) if n else None,
    }
    out = {"survey": cb["survey"], "summary": summary, "tables": tables}
    Path(outp).write_text(json.dumps(out, indent=1), encoding="utf-8")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
